     */
    plain?: boolean;
    /**
     * 是否文本按钮。
     * @default false
     */
    text?: boolean;
    /**
     * 文本按钮是否显示背景。
     * @default false
     */
    bg?: boolean;
    /**
     * 是否链接风格。
