     */
    link?: boolean;
    /**
     * 是否圆角。
     * @default false
     */
    round?: boolean;
    /**
     * 是否圆形按钮。
     * @default false
     */
    circle?: boolean;
    /**
     * 是否加载中。
     * @default false
     */
    loading?: boolean;
    /**
     * 图标名称。
     * 使用当前图标注册表中的图标名。
